"""Re-create the R019 long-text fixtures on the task's private PIM bus.

Source of truth for the payloads is r019-long-fixture.json (the recorded create
calls from round 019). Only disposable review content, isolated profile.
"""
import json
import os
import subprocess
from pathlib import Path

base = Path(__file__).resolve().parent
pid = (base / "live-app.pid").read_text().strip()
proc = Path("/proc") / pid
if not proc.exists() or b"--watch-qml" not in (proc / "cmdline").read_bytes():
    raise SystemExit("No owned live review app; refusing to target another session.")
environment = os.environ.copy()
environment["DBUS_SESSION_BUS_ADDRESS"] = (base / "live-bus-address").read_text().strip()

EVENT_FIELDS = ["title", "start", "end", "allDay", "calendarId", "description",
                "location", "recurrence", "reminderMinutes", "timeZone"]
TODO_FIELDS = ["title", "due", "listId", "allDay", "description", "recurrence",
               "reminderMinutes", "priority", "parentId"]


def call(method, *arguments):
    result = subprocess.run(["qdbus6", "org.nextkde.Kos.Pim1", "/Pim",
                             "org.nextkde.Kos.Pim1." + method, *arguments],
                            env=environment, capture_output=True, text=True)
    return {"method": method, "exit_code": result.returncode,
            "stdout": result.stdout, "stderr": result.stderr}


recorded = json.loads((base / "r019-long-fixture.json").read_text())
payloads = {}
for entry in recorded:
    item = json.loads(entry["result"])["item"]
    if entry["method"] == "createEvent":
        payloads["createEvent"] = {k: item[k] for k in EVENT_FIELDS}
    elif entry["method"] == "createTodo":
        payloads["createTodo"] = {k: item[k] for k in TODO_FIELDS}

results = []
for method in ("createEvent", "createTodo"):
    results.append(call(method, json.dumps(payloads[method], ensure_ascii=False)))
(base / "seed-long-output.json").write_text(
    json.dumps(results, ensure_ascii=False, indent=2) + "\n")
for r in results:
    print(r["method"], "exit", r["exit_code"], (r["stdout"] or r["stderr"]).strip()[:200])

